import{_ as t,o,c as i,a2 as a}from"./chunks/framework.BN2sqjC1.js";const u=JSON.parse('{"title":"Impostazioni e scorciatoie","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/impostazioni-scorciatoie.md","filePath":"user-guide/impostazioni-scorciatoie.md"}'),d={name:"user-guide/impostazioni-scorciatoie.md"};function r(c,e,n,l,s,p){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="impostazioni-e-scorciatoie" tabindex="-1">Impostazioni e scorciatoie <a class="header-anchor" href="#impostazioni-e-scorciatoie" aria-label="Permalink to &quot;Impostazioni e scorciatoie&quot;">​</a></h1><p>Aprite le impostazioni con <code>Mod+,</code> (o <em>Apri impostazioni</em>). Le impostazioni di editor, aspetto e scorciatoie sono <strong>per vault</strong> (file in <code>.clarae/</code>; i vault creati con la 1.x possono averli ancora nella cartella con il nome precedente: <a href="./installazione.html#aggiornare-dalla-1x">Aggiornare dalla 1.x</a>); lingua e tema valgono per l&#39;app. Se l&#39;amministratore ha bloccato una voce, compare disabilitata con l&#39;indicazione &quot;gestito dall&#39;amministratore&quot;.</p><table tabindex="0"><thead><tr><th>Sezione</th><th>Cosa contiene</th></tr></thead><tbody><tr><td>Generale</td><td>Lingua (sistema, italiano, inglese), tema (sistema, chiaro, scuro).</td></tr><tr><td>Editor</td><td>Modalità predefinita, numeri di riga (solo in Sorgente), a capo, larghezza leggibile, correzione ortografica, chiusura automatica delle coppie, incolla intelligente, ripiegamento dei titoli, dimensione del carattere, tabulazione.</td></tr><tr><td>File e link</td><td>Formato dei link (wikilink/Markdown, percorso più breve/relativo), dove creare le nuove note, dove salvare gli allegati, cestino (sistema o vault), conferma prima di eliminare, anteprima al passaggio.</td></tr><tr><td>Aspetto</td><td>Colore d&#39;accento (predefinito: il Teal del marchio; il colore predefinito della 1.x salvato in un vault vale come nessuna scelta, un colore scelto da voi resta), carattere e dimensione dell&#39;interfaccia, <strong>carattere e dimensione del carattere del terminale</strong> (predefiniti <code>MesloLGS NF</code>, da installare sul computer, e 13 px, tra 8 e 32; i due campi ci sono solo nel client desktop; vedi <a href="./terminale.html#il-carattere-del-terminale">Terminale</a>), zoom, barra di stato (spenta per default; anche dalla palette con <em>Mostra/nascondi barra di stato</em>).</td></tr><tr><td>Scorciatoie</td><td>Tutti i comandi con la scorciatoia attuale: cercate, riassegnate, rimuovete; i conflitti sono segnalati.</td></tr><tr><td>Note giornaliere e template</td><td>Cartella, formato data, template.</td></tr><tr><td>Cloud · Sincronizzazione · Condivisione</td><td>Server, account, dispositivi, intervallo di polling, inviti, mount.</td></tr><tr><td>Recupero file</td><td>Frequenza e limiti degli snapshot.</td></tr><tr><td>Informazioni</td><td>Versione, cartella dati.</td></tr></tbody></table><p>Non sono previsti plugin, temi di terze parti né CSS personalizzato: l&#39;aspetto si regola solo con le opzioni sopra.</p><h2 id="scorciatoie-predefinite" tabindex="-1">Scorciatoie predefinite <a class="header-anchor" href="#scorciatoie-predefinite" aria-label="Permalink to &quot;Scorciatoie predefinite&quot;">​</a></h2><p>(<strong>Mod</strong> = <code>Cmd</code> su macOS, <code>Ctrl</code> su Windows/Linux.) Tutte sono modificabili.</p><table tabindex="0"><thead><tr><th>Azione</th><th>Scorciatoia</th><th>Azione</th><th>Scorciatoia</th></tr></thead><tbody><tr><td>Nuova nota</td><td><code>Mod+N</code></td><td>Palette comandi</td><td><code>Mod+P</code> / <code>Mod+Maiusc+P</code></td></tr><tr><td>Nuova nota in una nuova scheda</td><td><code>Mod+Alt+N</code></td><td>Selettore rapido</td><td><code>Mod+O</code></td></tr><tr><td>Rinomina nota</td><td><code>F2</code></td><td>Cerca nel vault</td><td><code>Mod+Maiusc+F</code></td></tr><tr><td>Chiudi scheda / pannello</td><td><code>Mod+W</code> / <code>Mod+Maiusc+W</code></td><td>Scheda successiva / precedente</td><td><code>Mod+Alt+→</code> / <code>Mod+Alt+←</code></td></tr><tr><td>Dividi a destra / in basso</td><td><code>Mod+\\</code> / <code>Mod+Maiusc+\\</code></td><td>Vista lettura / sorgente</td><td><code>Mod+E</code> / <code>Mod+Maiusc+E</code></td></tr><tr><td>Barra sinistra / destra</td><td><code>Mod+Maiusc+L</code> / <code>+R</code></td><td>Vista grafo</td><td><code>Mod+Maiusc+G</code></td></tr><tr><td>Grassetto / corsivo</td><td><code>Mod+B</code> / <code>Mod+I</code></td><td>Evidenzia / barrato / codice</td><td><code>Mod+Maiusc+H</code> / <code>X</code> / <code>C</code></td></tr><tr><td>Link / wikilink</td><td><code>Mod+K</code> / <code>Mod+Maiusc+K</code></td><td>Elenco puntato / numerato / citazione</td><td><code>Mod+Maiusc+8</code> / <code>7</code> / <code>9</code></td></tr><tr><td>Attiva attività</td><td><code>Mod+Invio</code></td><td>Sincronizza ora</td><td><code>Mod+Maiusc+S</code></td></tr><tr><td>Impostazioni</td><td><code>Mod+,</code></td><td>Cerca nella nota</td><td><code>Mod+F</code></td></tr><tr><td>Vai alla riga</td><td><code>Mod+Alt+G</code></td><td>Terminale: mostra o nascondi</td><td><code>Ctrl+` </code> (anche su Mac)</td></tr><tr><td>Terminale: nuova scheda</td><td><code>Ctrl+Maiusc+` </code></td><td></td><td></td></tr></tbody></table><p><em>Cerca nella nota</em> apre la barra di ricerca dell&#39;editor, con espressioni regolari, distinzione delle maiuscole e «sostituisci tutto»: in Live è la barra propria di Live e cerca il testo reso (non i simboli Markdown), in Sorgente è il pannello di ricerca del testo; <em>Vai alla riga</em> chiede il numero di riga. Valgono per la nota aperta in Live o in Sorgente, non in Lettura.</p><p>Senza scorciatoia predefinita, ma nella palette e assegnabili da <em>Scorciatoie</em>: cambio vault, passaggio chiaro/scuro, blocca/sblocca scheda e chiusure delle schede (a destra, a sinistra, altre, tutte), nuova cartella, inserisci separatore, esporta come immagine, avvio della presentazione (dall&#39;inizio o dalla slide corrente), mostra le schede della barra destra (proprietà, link, slide, statistiche). Del terminale (solo nel client desktop, vedi <a href="./terminale.html">Terminale</a>) sono senza scorciatoia: chiudi la scheda, sgancia in una finestra separata, riaggancia; con il layout italiano su Windows e Linux <code>Mod+\\</code> resta <em>Dividi a destra</em> (conflitto noto).</p><p><strong>Applicazioni</strong> (solo dove c&#39;è il browser incorporato, cioè su macOS, e con la funzione accesa dal profilo): <em>Applicazione: indietro</em> <code>Mod+[</code>, <em>Applicazione: avanti</em> <code>Mod+]</code>, <em>Applicazione: ricarica</em> <code>Mod+R</code>; <em>Nuova applicazione</em>, <em>Apri applicazione…</em>, <em>Cambia l&#39;indirizzo dell&#39;applicazione</em>, <em>Apri l&#39;applicazione nel browser</em> ed <em>Elimina i dati delle applicazioni</em> non hanno scorciatoia. Vedi <a href="./applicazioni.html">Applicazioni</a>.</p><p>Nell&#39;<strong>albero dei file</strong>: frecce per muoversi, <code>→</code>/<code>←</code> per espandere/chiudere, <code>Invio</code> per aprire, <code>F2</code> per rinominare, <code>Canc</code> per spostare nel cestino, tasto Menu o <code>Maiusc+F10</code> per il menu contestuale. Vedi anche <a href="./accessibilita.html">Accessibilità</a>.</p>',11)])])}const h=t(d,[["render",r]]);export{u as __pageData,h as default};
